/**
 * Spec-driven tests for every v2.4 segment class generated from codegen/spec/v2.4-segments.json.
 *
 * The generated setters are uniform (a raw value, repetitions for a repeating field, a typed
 * composite object for the composite datatypes of utils/composites.ts), so one test file can
 * exercise all of them against the spec: every field has exactly one setter at the right position,
 * repeating fields encode `a~b`, composite objects encode their components in HL7 order, and a
 * fully populated segment survives a parse/encode round trip. A class generated as a subclass of an
 * older version's class (`extends` in the spec) is checked on the fields it adds or overrides; the
 * inherited ones are the base class's, covered by that version's tests.
 */
import { describe, test, expect } from "vitest";
import { existsSync, readFileSync, readdirSync } from "node:fs";
import { join } from "node:path";
import * as segments from "./index.ts";
import { DEFAULT_ENCODING } from "../types/encoding.ts";
import { BaseSegment } from "../types/segment.ts";

interface SpecField { seq: number; name: string; type: string; rep: string; opt: string; length: string; inherited?: boolean }
// vitest runs with the package as its working directory (pnpm -r runs each package in its own directory).
const ROOT = existsSync("codegen/spec/v2.4-segments.json") ? "." : "packages/hl7";
const SPEC: Record<string, { fields: SpecField[]; extends?: string }> = JSON.parse(readFileSync(join(ROOT, "codegen/spec/v2.4-segments.json"), "utf8"));
const DIR = join(ROOT, "src/v2.4");
const GENERATED = readdirSync(DIR)
  .filter((f) => f.endsWith(".ts") && !f.endsWith(".test.ts") && f !== "index.ts")
  .map((f) => f.replace(/\.ts$/, ""))
  .filter((code) => /Generated by codegen\/generate(-v23)?-segments\.ts/.test(readFileSync(join(DIR, `${code}.ts`), "utf8")))
  .sort();

type SegmentClass = { new (): BaseSegment & Record<string, unknown>; parse(s: string, e?: typeof DEFAULT_ENCODING): { ok: boolean; val?: BaseSegment } };
/** MSH, BHS and FHS carry the delimiters in their first two fields: field n is at wire position n - 1 and they parse without an encoding argument. */
const HEADER = new Set(["MSH", "BHS", "FHS"]);
const classOf = (code: string): SegmentClass => (segments as unknown as Record<string, SegmentClass>)[code];

/** A sample object and its HL7 encoding for each composite datatype the generator gives a typed setter. */
const COMPOSITES: Record<string, { value: Record<string, unknown>; encoded: string }> = {
  CE: { value: { identifier: "I", text: "T", nameOfCodingSystem: "S", alternateIdentifier: "AI", alternateText: "AT", nameOfAlternateCodingSystem: "AS" }, encoded: "I^T^S^AI^AT^AS" },
  CWE: { value: { code: "C", text: "T", codingSystem: "S" }, encoded: "C^T^S" },
  CX: { value: { idNumber: "ID", checkDigit: "7", checkDigitScheme: "M10", assigningAuthority: { namespaceId: "NS", universalId: "U", universalIdType: "ISO" }, identifierTypeCode: "MR", assigningFacility: "FAC" }, encoded: "ID^7^M10^NS&U&ISO^MR^FAC" },
  XCN: { value: { idNumber: "1", familyName: "Fam", givenName: "Giv", middleInitialOrName: "M", suffix: "Jr", prefix: "Dr", degree: "MD" }, encoded: "1^Fam^Giv^M^Jr^Dr^MD" },
  XPN: { value: { familyName: "Fam", givenName: "Giv", middleInitialOrName: "M", suffix: "Jr", prefix: "Dr", degree: "MD", nameTypeCode: "L" }, encoded: "Fam^Giv^M^Jr^Dr^MD^L" },
  XAD: { value: { streetAddress: "1 Main St", otherDesignation: "Apt 2", city: "Town", stateOrProvince: "ST", zipOrPostalCode: "12345", country: "USA", addressType: "H" }, encoded: "1 Main St^Apt 2^Town^ST^12345^USA^H" },
  XTN: { value: { telephoneNumber: "555-1234", telecommunicationUseCode: "PRN", telecommunicationEquipmentType: "PH", emailAddress: "a@b.c" }, encoded: "555-1234^PRN^PH^a@b.c" },
  EI: { value: { entityIdentifier: "E1", namespaceId: "NS", universalId: "U", universalIdType: "ISO" }, encoded: "E1^NS^U^ISO" },
  PI: { value: { idNumber: "P1", typeOfIdNumber: "T", otherQualifyingInfo: "Q" }, encoded: "P1^T^Q" },
  PL: { value: { pointOfCare: "POC", room: "R1", bed: "B1", facility: { namespaceId: "F" }, locationStatus: "A", personLocationType: "C", building: "BLD", floor: "3" }, encoded: "POC^R1^B1^F^A^C^BLD^3" },
  CP: { value: { price: { quantity: "10.50", denomination: "USD" }, priceType: "TP", fromValue: "1", toValue: "2", rangeUnits: { identifier: "U" }, rangeType: "P" }, encoded: "10.50&USD^TP^1^2^U^P" },
  PLN: { value: { idNumber: "L1", typeOfIdNumber: "T", stateOtherQualifyingInformation: "ST", expirationDate: "20301231" }, encoded: "L1^T^ST^20301231" },
  LA2: { value: { pointOfCare: "POC", room: "R1", bed: "B1" }, encoded: "POC^R1^B1" },
  XON: { value: { organizationName: "Org", organizationNameTypeCode: "L", idNumber: "9", checkDigit: "1", checkDigitScheme: "M10", assigningAuthority: "AA", identifierTypeCode: "FI" }, encoded: "Org^L^9^1^M10^AA^FI" },
  MO: { value: { quantity: "19.99", denomination: "USD" }, encoded: "19.99^USD" },
  CQ: { value: { quantity: "5", units: { identifier: "mg", text: "milligram", nameOfCodingSystem: "ISO+" } }, encoded: "5^mg&milligram&ISO+" },
  TQ: { value: { quantity: { quantity: "1", units: "TAB" }, interval: { repeatPattern: "Q6H", explicitTimeInterval: "0600,1200" }, duration: "D7", startDateTime: "20231015", endDateTime: "20231022", priority: "R", condition: "PRN", text: "as needed", conjunction: "C", orderSequencing: { sequenceResultsFlag: "S", placerOrderNumberEntityIdentifier: "P1" } }, encoded: "1&TAB^Q6H&0600,1200^D7^20231015^20231022^R^PRN^as needed^C^S&P1" },
  DR: { value: { rangeStartDateTime: "20231015", rangeEndDateTime: "20231016" }, encoded: "20231015^20231016" },
  RI: { value: { repeatPattern: "Q8H", explicitTimeInterval: "0800,1600,0000" }, encoded: "Q8H^0800,1600,0000" },
  PPN: { value: { idNumber: "1", familyName: "Fam", givenName: "Giv", middleInitialOrName: "M", suffix: "Jr", prefix: "Dr", degree: "MD", sourceTable: "T", assigningAuthority: { namespaceId: "NS" }, nameTypeCode: "L", identifierCheckDigit: "7", checkDigitScheme: "M10", identifierTypeCode: "MD", assigningFacility: "FAC", dateTimeActionPerformed: "20231015120000" }, encoded: "1^Fam^Giv^M^Jr^Dr^MD^T^NS^L^7^M10^MD^FAC^20231015120000" },
  CK: { value: { idNumber: "123", checkDigit: "4", checkDigitScheme: "M11", assigningAuthority: { namespaceId: "NS", universalId: "U", universalIdType: "ISO" } }, encoded: "123^4^M11^NS&U&ISO" },
  VH: { value: { startDayRange: "MON", endDayRange: "FRI", startHourRange: "0900", endHourRange: "1700" }, encoded: "MON^FRI^0900^1700" },
  SCV: { value: { parameterClass: "PRIM", parameterValue: "Y" }, encoded: "PRIM^Y" },
  QIP: { value: { fieldName: "@PID.5.1", values: ["SMITH", "JONES"] }, encoded: "@PID.5.1^SMITH&JONES" },
  QSC: { value: { nameOfField: "@PID.3", relationalOperator: "EQ", value: "123", relationalConjunction: "AND" }, encoded: "@PID.3^EQ^123^AND" },
  RCD: { value: { hl7ItemNumber: "00108", hl7DataType: "ST", maximumColumnWidth: "20" }, encoded: "00108^ST^20" },
  CM_PI: { value: { idNumber: "P1", typeOfIdNumber: "T", otherQualifyingInfo: "Q" }, encoded: "P1^T^Q" },
  CM_RANGE: { value: { lowValue: "3.5", highValue: "5.0" }, encoded: "3.5^5.0" },
  CM_RFR: { value: { referenceRange: { lowValue: "3.5", highValue: "5.0" }, sex: "F", ageRange: { lowValue: "18", highValue: "65" }, ageGestation: "20&40", species: "human", raceSubspecies: "any", conditions: "fasting" }, encoded: "3.5&5.0^F^18&65^20&40^human^any^fasting" },
  CM_ABS_RANGE: { value: { range: { lowValue: "0", highValue: "100" }, numericChange: "10", percentPerChange: "5", days: "2" }, encoded: "0&100^10^5^2" },
  CM_DLT: { value: { range: "1&9", numericThreshold: "2", change: "%", lengthOfTimeDays: "30" }, encoded: "1&9^2^%^30" },
};

/** Date and date/time fields format a Date with the HL7 layout. */
const DATES: Record<string, { value: Date; encoded: string }> = {
  TS: { value: new Date(2023, 9, 15, 9, 30, 5), encoded: "20231015093005" },
  DT: { value: new Date(2023, 9, 15, 9, 30, 5), encoded: "20231015" },
};

const SENTINEL = "ZQXP0S";
const isRepeating = (f: SpecField) => f.rep !== "-" && f.rep !== "";

/** The setters of a generated class, found by calling each public method with a sentinel and seeing which field it writes. */
function settersOf(code: string): Map<number, string[]> {
  const cls = classOf(code);
  const map = new Map<number, string[]>();
  const skip = new Set(["constructor", "encode", "parse", "getField", "getName"]);
  for (const name of Object.getOwnPropertyNames(cls.prototype)) {
    if (skip.has(name) || typeof (cls.prototype as Record<string, unknown>)[name] !== "function") continue;
    const seg = new cls();
    let encoded: string;
    try {
      (seg[name] as (v: string) => unknown)(SENTINEL);
      encoded = seg.encode();
    } catch {
      continue;
    }
    const index = encoded.split("|").findIndex((p, i) => i > 0 && p.split("^")[0] === SENTINEL);
    // MSH, BHS and FHS: wire position n holds field n + 1 (field 1 is the separator itself).
    const seq = HEADER.has(code) ? index + 1 : index;
    if (index > 0) map.set(seq, [...(map.get(seq) ?? []), name]);
  }
  return map;
}

describe.each(GENERATED)("%s (generated from the spec)", (code) => {
  const spec = SPEC[code];
  const cls = classOf(code);
  const setters = settersOf(code);

  test("exists in the spec and the barrel", () => {
    expect(spec).toBeDefined();
    expect(typeof cls).toBe("function");
  });

  const own = spec.fields.filter((f) => !f.inherited);
  const header = HEADER.has(code);

  test("has one setter per spec field and none beyond the last field", () => {
    for (const f of own) expect(setters.get(f.seq), `${code}-${f.seq} ${f.name}`).toBeDefined();
    for (const index of setters.keys()) expect(index, `setter at ${code}-${index}`).toBeLessThanOrEqual(spec.fields.length);
  });

  test.each(own.map((f) => [f.seq, f.name, f] as const))(`${code}-%i %s`, (seq, _name, f) => {
    const [setter] = setters.get(seq)!;
    const call = (value: unknown) => {
      const seg = new cls();
      (seg[setter] as (v: unknown) => unknown)(value);
      return seg.encode().split("|")[header ? seq - 1 : seq];
    };
    expect(call("v")).toBe("v");
    if (isRepeating(f)) expect(call(["a", "b"]), "repetitions").toBe("a~b");
    const date = DATES[f.type];
    if (date) {
      expect(call(date.value), `${f.type} from a Date`).toBe(date.encoded);
      if (isRepeating(f)) expect(call([date.value, "20000101"]), `${f.type} repetitions`).toBe(`${date.encoded}~20000101`);
    }
    const composite = COMPOSITES[f.type];
    if (composite) {
      expect(call(composite.value), `${f.type} components`).toBe(composite.encoded);
      if (isRepeating(f)) expect(call([composite.value, "x"]), `${f.type} repetitions`).toBe(`${composite.encoded}~x`);
    }
  });

  test("round-trips a fully populated segment", () => {
    const body = spec.fields.filter((f) => !header || f.seq > 2).map((f) => (isRepeating(f) ? `r${f.seq}a^c~r${f.seq}b` : `v${f.seq}^c&s`));
    const wire = header ? `${code}|^~\\&|${body.join("|")}` : `${code}|${body.join("|")}`;
    const parsed = header ? cls.parse(wire) : cls.parse(wire, DEFAULT_ENCODING);
    expect(parsed.ok).toBe(true);
    expect(parsed.val!.encode()).toBe(wire);
    expect(cls.parse("ZZZ|1", DEFAULT_ENCODING).ok).toBe(false);
  });
});
